import logging
from pathlib import Path

from tortoise import Tortoise, connections
from tortoise.transactions import in_transaction

from . import db

log = logging.getLogger("tolktak")

# Tables whose id column is generated by the database.
IDENTITY = ["users", "sessions", "channels", "groups", "rooms", "messages"]
BATCH = 500
# A unique sort order per table, so batches neither skip nor repeat rows.
ORDER = {
    "invites": "code",
    "channel_members": "channel_id, user_id",
    "group_members": "group_id, user_id",
    "files": "id",
    "reactions": "message_id, emoji, user_id",
    "text_channels": "channel_id",
}


def _conn(url: str):
    return db.db_config(url, Path("."))["connections"][db.CONN]


async def copy(src_url: str, dst_url: str) -> int:
    if not src_url or not dst_url:
        log.error("both database URLs are required")
        return 2
    await Tortoise.init(
        config={
            "connections": {db.CONN: _conn(dst_url), "src": _conn(src_url)},
            "apps": {"tolktak": {"models": ["tolktak.models"], "default_connection": db.CONN}},
        }
    )
    try:
        src, dst = connections.get("src"), connections.get(db.CONN)
        await db.migrate(src)
        await db.migrate(dst)
        if (await db.rows("SELECT COUNT(*) AS n FROM users", c=dst))[0]["n"]:
            log.error("the destination database is not empty")
            return 1
        async with in_transaction(db.CONN) as tx:
            for table in db.TABLES:
                n = await _copy_table(src, tx, table)
                log.info("copied table=%s rows=%d", table, n)
            if db.is_postgres(dst):
                for table in IDENTITY:
                    await tx.execute_query(
                        f"SELECT setval(pg_get_serial_sequence('{table}', 'id'), "
                        f"COALESCE((SELECT MAX(id) FROM {table}), 0) + 1, false)"
                    )
        log.info("copy complete")
        return 0
    finally:
        await db.close()


async def _copy_table(src, dst, table: str) -> int:
    total = 0
    offset = 0
    while True:
        batch = await src.execute_query_dict(
            f"SELECT * FROM {table} ORDER BY {ORDER.get(table, 'id')} LIMIT {BATCH} OFFSET {offset}"
        )
        if not batch:
            return total
        cols = list(batch[0])
        q = db.sql(f"INSERT INTO {table} ({', '.join(cols)}) VALUES ({', '.join('?' * len(cols))})", dst)
        for row in batch:
            await dst.execute_query(q, [_value(row[c]) for c in cols])
        total += len(batch)
        offset += BATCH


def _value(v):
    return bytes(v) if isinstance(v, memoryview) else v
